   if first['value']=='create':
    _require(len(tokens)==3 and tokens[1]['kind']=='word' and tokens[1]['value']=='role' and tokens[2]['kind'] in ['word','identifier'],'ROLE_SCRIPT_CREATE_FORM_UNSUPPORTED')
