 name=source_identity.get('bootstrapName');_require(type(name) is str and name and name.isascii() and len(name.encode())<=63,'SOURCE_BOOTSTRAP_PROVENANCE_INVALID')
 _restore_identifier(name)
 _require(_bootstrap_oid(source_identity.get('bootstrapOid'))==10 and type(source_identity.get('serverVersionNum')) is int and source_identity['serverVersionNum']==170006,'SOURCE_BOOTSTRAP_PROVENANCE_INVALID')
 _require(destination_identity.get('bootstrapName')==name and _bootstrap_oid(destination_identity.get('bootstrapOid'))==10 and type(destination_identity.get('serverVersionNum')) is int and destination_identity['serverVersionNum']==170006,'DESTINATION_BOOTSTRAP_IDENTITY_MISMATCH')
 _require(not re.search(rb'\bPASSWORD\s+\S+',raw,re.I),'ROLE_PASSWORD')
 parsed=_scan_roles(raw);hits=[s for s in parsed['statements'] if s['createRole']==name]
 _require(len(hits)>0,'BOOTSTRAP_CREATE_ZERO_MATCH');_require(len(hits)==1,'BOOTSTRAP_CREATE_MULTIPLE_MATCH')
 item=hits[0];_require(not item['hasInternalComment'],'BOOTSTRAP_CREATE_INTERNAL_COMMENT_AMBIGUITY')
 a,z=item['start'],item['end'];output=raw[:a]+raw[z:]
 _require(output[:a]==raw[:a] and output[a:]==raw[z:],'DERIVATION_BYTE_PRESERVATION')
 return output,{'profile':parsed['profile'],'sourceBootstrapIdentity':copy.deepcopy(source_identity),'destinationBootstrapIdentity':copy.deepcopy(destination_identity),
  'originalBytes':len(raw),'originalSha256':sha(raw),'derivedBytes':len(output),'derivedSha256':sha(output),'matchCount':1,'bootstrapIdentifier':name,
  'removedSpan':{'startByteInclusive':a,'endByteExclusive':z,'statementIndexOneBased':item['index'],'lineOneBased':raw[:a].count(b'\n')+1},
  'removedExactStatement':raw[a:z].decode('ascii'),'removedStatementSha256':sha(raw[a:z]),'prefixSha256':sha(raw[:a]),'suffixSha256':sha(raw[z:]),
  'prefixByteExact':True,'suffixByteExact':True,'originalNeverModified':True,'allOtherStatementsAndCommentsPreserved':True,'originalMetaCommands':parsed['metaCommands']}
