class OwnedCluster:
    """Disposable PG17 used for restore verification and owned tests only."""
    def __init__(self):
        self.name='uply-runner-i1-'+uuid.uuid4().hex
        self.closed=False
        with _diagnostic_phase('E1'), _diagnostic_operation('OWNED_CLUSTER_RUN', self.name):
            _docker(['run','--rm','-d','--pull=never','--network','none','--name',self.name,
                     '--label','uply.task=runner-i1','--read-only','--tmpfs','/tmp:rw,size=2048m,mode=1777',
                     '--user','100:101','--entrypoint','/bin/sh',IMAGE_ID,'-c',
                     "initdb -D /tmp/pg -A trust --no-locale >/tmp/init.log && exec postgres -D /tmp/pg -k /tmp -c listen_addresses='' -c max_connections=30"])
        try:
            with _diagnostic_phase('E2'):
                for _ in range(100):
                    try:
                        with _diagnostic_operation('OWNED_PG_ISREADY', self.name):
                            _docker(['exec',self.name,'pg_isready','-h','/tmp','-U','postgres']);break
                    except Failure:time.sleep(0.1)
                else:raise Failure('BACKUP_FAILED','OWNED_DB_START')
                self.transport=OwnedTransport(self.name)
        except Exception as error:_close_preserving(self.close, error);raise

    def close(self):
        if not self.closed:
            with _diagnostic_phase('E9'):
                OwnedTransport(self.name)._inspect()
                with _diagnostic_operation('OWNED_STOP', self.name):
                    _docker(['stop','--time','2',self.name]);self.closed=True
                for _ in range(50):
                    with _diagnostic_operation('OWNED_REMOVAL_CHECK', self.name):
                        if not _docker(['ps','-aq','--filter','name=^/'+self.name+'$']).strip():break
                    time.sleep(0.1)
                else:raise Failure('BACKUP_FAILED','CLEANUP_FAILED')

    def __enter__(self):return self
    def __exit__(self,kind,error,traceback):_close_preserving(self.close, error)


def _write_bytes(path,raw):
    fd=os.open(path,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
    try:
        with os.fdopen(fd,'wb',closefd=False) as f:f.write(raw);f.flush();os.fsync(fd)
    finally:os.close(fd)
    d=os.open(Path(path).parent,os.O_RDONLY|os.O_DIRECTORY)
    try:os.fsync(d)
    finally:os.close(d)


def _counts(s):
    # Identifiers originate only in server catalog and are quoted with server format('%I').
    query=s._json("""select to_jsonb('select coalesce(jsonb_object_agg(k,v),''{}'') from ('||
      string_agg(format('select %L as k, count(*) as v from %I.%I',n.nspname||'.'||c.relname,n.nspname,c.relname),' union all ' order by n.nspname,c.relname)||') x')
      from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind='r' and n.nspname not like 'pg_%' and n.nspname<>'information_schema';""")
    return s._json(query+';')


