def _role_config_supported(config):
    """Bounded global role defaults; preserve catalog values and array order."""
    if config is None:
        return True
    if type(config) is not list or len(config) > 2:
        return False
    seen = set()
    for entry in config:
        if type(entry) is not str:
            return False
        key, separator, value = entry.partition('=')
        if not separator or key in seen:
            return False
        seen.add(key)
        if key == 'statement_timeout':
            if re.fullmatch(r'[0-9]+(?:ms|s|min|h|d)?', value) is None:
                return False
        elif key == 'search_path':
            if re.fullmatch(r'[a-z_][a-z0-9_]{0,62}(, [a-z_][a-z0-9_]{0,62})?', value) is None:
                return False
            components = value.split(', ')
            if len(set(components)) != len(components) or any(
                    name.startswith('pg_') or name == 'information_schema' for name in components):
                return False
        else:
            return False
    return True


def _role_rows(rows):
    _require(type(rows) is list and rows, 'OWNED_ROLE_REPLAY_INCOMPLETE')
    names = []
    for row in rows:
        _require(type(row) is list and len(row) == 11, 'OWNED_ROLE_REPLAY_INCOMPLETE')
        _restore_identifier(row[0]); names.append(row[0])
        _require(all(type(v) is bool for v in row[1:8]) and
                 type(row[8]) is int and row[8] >= -1 and
                 (row[9] is None or type(row[9]) is str), 'OWNED_ROLE_REPLAY_INCOMPLETE')
        _require(_role_config_supported(row[10]), 'ROLE_FIDELITY_PROFILE_UNSUPPORTED')
    _require(len(set(names)) == len(names), 'OWNED_ROLE_REPLAY_INCOMPLETE')
    return rows


def _source_collision(expected):
    _role_rows(expected['roles'])
    _require(not any(row[0] == OWNED_RESTORE_ADMIN for row in expected['roles']),
             'OWNED_RESTORE_ADMIN_SOURCE_COLLISION')


def _identity(response):
    code = 'SOURCE_BOOTSTRAP_PROVENANCE_INVALID'
    _require(type(response) is dict and set(response) == {
        'database','session_user','current_user','serverVersionNum','serverVersion',
        'serverEncoding','clientEncoding','bootstrapRows'}, code)
    _require(type(response['serverVersionNum']) is int and response['serverVersionNum'] == 170006,
             'SOURCE_RECOVERY_PROFILE_UNSUPPORTED')
    _require(response['serverVersion'] == '17.6' and response['database'] == 'postgres', code)
    _require(response['serverEncoding'] in ('UTF8','SQL_ASCII') and
             response['clientEncoding'] == response['serverEncoding'], 'SOURCE_RECOVERY_PROFILE_UNSUPPORTED')
    for k in ['session_user','current_user']:
        _restore_identifier(response[k])
    rows = response['bootstrapRows']
    _require(type(rows) is list and len(rows) == 1 and type(rows[0]) is dict, code)
    row = rows[0]
    _require(set(row) == {'bootstrapOid','bootstrapName','roleTuple'}, code)
    oid = _bootstrap_oid(row['bootstrapOid']); _restore_identifier(row['bootstrapName'])
    _role_rows([row['roleTuple']])
    _require(row['roleTuple'][0] == row['bootstrapName'] and row['roleTuple'][1] is True, code)
    return {'bootstrapOid':oid,'bootstrapName':row['bootstrapName'],
            'serverVersionNum':response['serverVersionNum']}


def _proof_ref(key, record):
    p = record['proof']
    _require(record['sha256'] == sha(canonical(p)+b'\n'), 'SOURCE_BOOTSTRAP_CAPTURE_BINDING_MISMATCH')
    return {'record':key,'sha256':record['sha256'],'invocationId':p['invocationId']}


def _read_json(session, query):
    # _Session._exchange has already removed protocol framing: canonical JSON only.
    return strict_json(session._exchange(query))


def _measure_bootstrap(session, phase, record, context):
    start = time.time()
    response = _read_json(session, BOOTSTRAP_SQL)
    _identity(response)
    row = response['bootstrapRows'][0]
    return {'phase':phase,'measuredAtUtc':datetime.datetime.now(datetime.timezone.utc).isoformat(),
            'startedAt':start,'completedAt':time.time(),'monotonicSequence':1 if phase == 'PRE' else 2,
            'querySha256':BOOTSTRAP_QUERY_SHA,'canonicalResponse':response,
            'canonicalResponseSha256':sha(canonical(response)),
            'rawBootstrapOid':row['bootstrapOid'],'rawBootstrapOidType':type(row['bootstrapOid']).__name__,
            'normalizedBootstrapOid':10,'transportProofRef':_proof_ref('exporter' if phase == 'PRE' else 'afterObservation', record),
            'sourceIdentitySha256':context['sourceIdentitySha256'],'captureId':context['captureId'],
            'rawResponseAvailable':False,'rawResponseSha256':None}


def _plpgsql_profile(state):
    _require(type(state) is dict and set(state) == set(_PLPGSQL_TEMPLATE), 'SOURCE_RECOVERY_PROFILE_UNSUPPORTED')
    rows = [row for row in state['extensions'] if row[0] == 'plpgsql']
    _require(len(rows) == 1 and len(rows[0]) == 4, 'SOURCE_RECOVERY_PROFILE_UNSUPPORTED')
    owner = rows[0][3]; _restore_identifier(owner)
    wanted = copy.deepcopy(_PLPGSQL_TEMPLATE)
    wanted['extensions'][0][3] = owner
    wanted['plpgsqlLanguage'][1] = owner
    for row in wanted['implementation']: row[3] = owner
    actual = dict(state, extensions=rows)
    _require(canonical(actual) == canonical(wanted), 'SOURCE_RECOVERY_PROFILE_UNSUPPORTED')
    return actual


def _unsupported_families(value):
    _require(type(value) is dict and set(value) == {
        'roleComments','roleSecurityLabels','databaseRoleSettings','parameterAcl'} and
        all(v == [] for v in value.values()), 'ROLE_FIDELITY_PROFILE_UNSUPPORTED')


def _extension_branch(state):
    """Closed install template; this projection never normalizes source fidelity."""
    code = 'SOURCE_RECOVERY_PROFILE_UNSUPPORTED'
    _require(type(state) is dict and set(state) == set(_EXTENSION_FAMILIES) and
             all(type(state[k]) is list for k in _EXTENSION_FAMILIES), code)
    if state['extensions'] == []:
        _require(all(state[k] == [] for k in _EXTENSION_FAMILIES), code)
        return 'PLPGSQL_ONLY'
    for family in ['extensions','members']:
        rows = state[family]; template = _EXTENSION_TEMPLATE[family]
        _require(len(rows) == len(template), code)
        for row,wanted in zip(rows,template):
            _require(type(row) is dict and set(row) == set(wanted) | {'owner'} and
                     type(row['owner']) is str and bool(row['owner']), code)
            _require(canonical({k:v for k,v in row.items() if k != 'owner'}) == canonical(wanted), code)
    return 'BOOTSTRAP_OWNED_FIXED_EXTENSION_SET'


def _extension_state(state, catalog, identity):
    """Validate measured owners/ACL domain separately from the invariant template."""
    code = 'SOURCE_RECOVERY_PROFILE_UNSUPPORTED'
    try:
        branch = _extension_branch(state)
        roles = _role_rows(catalog['roles']); names = {r[0] for r in roles}
        bootstrap = identity['bootstrapName']
        _require(type(identity['bootstrapOid']) is int and identity['bootstrapOid'] == 10 and
                 type(identity['serverVersionNum']) is int and identity['serverVersionNum'] == 170006, code)
        _require(len([r for r in roles if r[0] == bootstrap and r[1] is True]) == 1, code)
        projected = [[r['name'],r['version'],r['schema'],r['owner']] for r in state['extensions']]
        _require(projected == [r for r in catalog['extensions'] if r[0] != 'plpgsql'], code)
        if branch == 'PLPGSQL_ONLY': return branch
        _require('PUBLIC' not in names and OWNED_RESTORE_ADMIN not in names, code)
        _require(all(r['owner'] == bootstrap for k in ['extensions','members'] for r in state[k]), code)
        keys = {(r['extension'],r['class'],r['identity']) for r in state['members']}
        acl_keys = {k for k in keys if k[1] in ('pg_proc','pg_type')}
        raw_rows = {}
        for row in state['rawAcl']:
            _require(type(row) is list and len(row) == 5 and all(type(v) is str for v in row[:4]), code)
            key = tuple(row[:3]); raw_acl = row[4]
            _require(key in acl_keys and key not in raw_rows and row[3] == bootstrap, code)
            _require(raw_acl is None or (key[1] == 'pg_proc' and type(raw_acl) is list and
                     all(type(v) is str for v in raw_acl)), code)
            raw_rows[key] = raw_acl
        _require(set(raw_rows) == acl_keys, code)
        expanded = {}; seen = set()
        for row in state['expandedAcl']:
            _require(type(row) is list and len(row) == 7 and all(type(v) is str for v in row[:6]) and
                     row[6] is False, code)
            key = tuple(row[:3]); item = tuple(row)
            _require(key in acl_keys and item not in seen and row[3] == bootstrap and
                     row[4] in names | {'PUBLIC'} and row[5] == ('EXECUTE' if key[1]=='pg_proc' else 'USAGE'), code)
            seen.add(item); expanded.setdefault(key,[]).append(row[3:])
        for key,raw_acl in raw_rows.items():
            if raw_acl is None:
                privilege = 'EXECUTE' if key[1]=='pg_proc' else 'USAGE'
                _require(sorted(expanded.get(key,[])) == sorted([[bootstrap,n,privilege,False] for n in ['PUBLIC',bootstrap]]), code)
            if raw_acl == []: _require(expanded.get(key,[]) == [], code)
        effective = set()
        for row in state['effective']:
            _require(type(row) is list and len(row) == 5 and all(type(v) is str for v in row[:4]) and type(row[4]) is bool, code)
            key = tuple(row[:4]); _require(key not in effective, code); effective.add(key)
        _require(effective == {key+(role,) for key in acl_keys for role in names}, code)
        initial_keys = set()
        for row in state['initialPrivileges']:
            _require(type(row) is dict and set(row) == {'extension','class','identity','subid','origin','raw','expanded'}, code)
            _require(all(type(row[k]) is str for k in ['extension','class','identity','origin']) and
                     type(row['subid']) is int and row['subid'] == 0 and row['origin'] in ('e','i'), code)
            key = (row['extension'],row['class'],row['identity'])
            _require(key in keys and key not in initial_keys, code); initial_keys.add(key)
            _require(row['raw'] is None or (type(row['raw']) is list and all(type(v) is str for v in row['raw'])), code)
            _require(row['expanded'] is None or type(row['expanded']) is list, code)
            for item in row['expanded'] or []:
                _require(type(item) is list and len(item) == 4 and all(type(v) is str for v in item[:3]) and
                         type(item[3]) is bool and item[0] in names and item[1] in names | {'PUBLIC'}, code)
        return branch
    except Failure: raise
    except (KeyError,TypeError,ValueError,IndexError):
        raise Failure('BACKUP_FAILED',code) from None


def _extension_guard(guard, catalog, branch):
    """Finite ACL source guard. No raw aclitem parsing or dotted-name guessing."""
    code = 'SOURCE_RECOVERY_PROFILE_UNSUPPORTED'
    try:
        _require(type(guard) is dict and set(guard) == {'owners','acls','expandedAcl','extensionMembers','databaseOwner'}, code)
        _require(type(guard['databaseOwner']) is str and bool(guard['databaseOwner']) and
                 all(guard[k] is None or type(guard[k]) is list for k in ['owners','acls','expandedAcl','extensionMembers']), code)
        owner_kinds = {'namespace','relation','function','type','extension','language','default'}
        acl_kinds = {'namespace','relation','column','function','type','default','language','database'}
        owners = {}; acls = {}
        for row in guard['owners'] or []:
            _require(type(row) is list and len(row) == 3 and all(type(x) is str for x in row) and row[0] in owner_kinds, code)
            _require(row[0]!='language' or row[1]=='plpgsql',code)
            _require(row[0]!='default' or re.fullmatch(r'[1-9][0-9]*',row[1]) is not None,code)
            key=tuple(row[:2]); _require(key not in owners,code); owners[key]=row[2]
        for row in guard['acls'] or []:
            _require(type(row) is list and len(row) == 3 and all(type(x) is str for x in row[:2]) and
                     (row[2] is None or type(row[2]) is str) and row[0] in acl_kinds, code)
            _require(row[0]!='language' or row[1]=='plpgsql',code)
            _require(row[0]!='database' or row[1]=='postgres',code)
            _require(row[0]!='default' or re.fullmatch(r'[1-9][0-9]*',row[1]) is not None,code)
            key=tuple(row[:2]); _require(key not in acls,code); acls[key]=row[2]
        for row in guard['extensionMembers'] or []:
            _require(type(row) is dict and set(row)=={'extension','class','description'} and
                     all(type(v) is str for v in row.values()), code)
        for row in guard['expandedAcl'] or []:
            _require(type(row) is list and len(row)==6 and all(type(v) is str for v in row[:5]) and
                     type(row[5]) is bool and tuple(row[:2]) in acls, code)
        if branch == 'PLPGSQL_ONLY': return
        names = {r[0] for r in catalog['roles']}
        _require(guard['databaseOwner'] in names and all(v in names for v in owners.values()), code)
        relations = {}; relation_owners = {}; columns = {}
        for row in catalog['relations']:
            key=tuple(row[:2]); text='.'.join(key)
            _require(key not in relations and text not in relation_owners,code)
            relations[key]=row[3];relation_owners[text]=row[3]
            _require(owners.get(('relation',text))==row[3] and ('relation',text) in acls,code)
        for row in catalog['columns']:
            key=tuple(row[:2]);text='.'.join(row[:3])
            _require(key in relations and text not in columns and ('column',text) in acls,code);columns[text]=relations[key]
        _require({k[1] for k in owners if k[0]=='relation'}==set(relation_owners) and
                 {k[1] for k in acls if k[0]=='relation'}==set(relation_owners) and
                 {k[1] for k in acls if k[0]=='column'}==set(columns),code)
        namespace_names={row[0] for row in catalog['namespaces']}
        _require({k[1] for k in owners if k[0]=='namespace'}==namespace_names and
                 {k[1] for k in acls if k[0]=='namespace'}==namespace_names,code)
        for row in catalog['namespaces']:
            _require(owners.get(('namespace',row[0]))==row[1] and ('namespace',row[0]) in acls,code)
        for row in catalog['functions']:
            _require(owners.get(('function',row['signature']))==row['owner'] and ('function',row['signature']) in acls and
                     acls.get(('function',row['signature']))==row['acl'],code)
        for row in catalog['types']:
            _require(owners.get(('type',row[0]+'.'+row[1]))==row[3] and ('type',row[0]+'.'+row[1]) in acls,code)
        for row in catalog['extensions']:
            _require(owners.get(('extension',row[0]))==row[3],code)
            if row[0]=='plpgsql':
                _require(owners.get(('language','plpgsql'))==row[3] and
                         ('language','plpgsql') in acls and acls[('language','plpgsql')] is None,code)
        for row in guard['expandedAcl'] or []:
            kind,ident,grantor,grantee,privilege,grantable=row
            _require(grantor in names and grantee in names | {'PUBLIC'},code)
            if kind=='column': owner=columns.get(ident)
            elif kind=='relation': owner=relation_owners.get(ident)
            elif kind=='database':
                _require(ident=='postgres',code);owner=guard['databaseOwner']
            else: owner=owners.get((kind,ident))
            _require(owner is not None and grantor==owner,code)
    except Failure: raise
    except (KeyError,TypeError,ValueError,IndexError):
        raise Failure('BACKUP_FAILED',code) from None


def _extension_envelope(state, guard):
    return {'profileName':EXTENSION_PROFILE,'profileVersion':EXTENSION_PROFILE_VERSION,
            'branch':_extension_branch(state),'extensionState':state,'archiveAclContextGuard':guard,
            'measurementCoverage':copy.deepcopy(_EXTENSION_COVERAGE)}


def _extension_prerequisite(envelope, catalog, identity):
    code='SOURCE_RECOVERY_PROFILE_UNSUPPORTED'
    _require(type(envelope) is dict and set(envelope)=={
        'profileName','profileVersion','branch','extensionState','archiveAclContextGuard','measurementCoverage'},code)
    _require(envelope['profileName']==EXTENSION_PROFILE and type(envelope['profileVersion']) is int and
             envelope['profileVersion']==EXTENSION_PROFILE_VERSION and
             canonical(envelope['measurementCoverage'])==canonical(_EXTENSION_COVERAGE),code)
    branch=_extension_state(envelope['extensionState'],catalog,identity)
    _require(envelope['branch']==branch,code)
    _extension_guard(envelope['archiveAclContextGuard'],catalog,branch)
    return branch


def _prerequisite_queries():
    return [('plpgsqlExpectedState',PLPGSQL_SQL),('databaseAclBeforeCapture',DATABASE_ACL_SQL),
            ('unsupportedRoleFamilies',UNSUPPORTED_ROLE_FAMILIES_SQL),
            ('extensionRecoveryExpectedState.extensionState',EXTENSION_SQL),
            ('extensionRecoveryExpectedState.archiveAclContextGuard',SOURCE_COUNTERPART_SQL)]


def _prerequisite_value(values,key):
    # These dotted keys are a closed contract, not caller-controlled path traversal.
    if key.startswith('extensionRecoveryExpectedState.'):
        return values['extensionRecoveryExpectedState'][key.split('.')[1]]
    return values[key]


def _restore_argv(container, branch, identity):
    _require(type(container) is str and re.fullmatch(r'uply-runner-i1-[0-9a-f]{32}',container) is not None)
    _require(branch in ('PLPGSQL_ONLY','BOOTSTRAP_OWNED_FIXED_EXTENSION_SET'))
    name=identity['bootstrapName'];_restore_identifier(name)
    args=['exec','-i',container,'pg_restore','--exit-on-error','-h','/tmp','-U',OWNED_RESTORE_ADMIN]
    if branch=='BOOTSTRAP_OWNED_FIXED_EXTENSION_SET':args+=['--role',name]
    return args+['-d','postgres']


def _restore_execution_context(argv, full, branch, identity):
    _require(type(argv) is list and len(argv)>=3 and argv==_restore_argv(argv[2],branch,identity))
    return {'profileName':EXTENSION_PROFILE,'profileVersion':EXTENSION_PROFILE_VERSION,'branch':branch,
            'authenticatedRole':OWNED_RESTORE_ADMIN,
            'startupEffectiveRole':identity['bootstrapName'] if branch=='BOOTSTRAP_OWNED_FIXED_EXTENSION_SET' else OWNED_RESTORE_ADMIN,
            'identityEvidenceKind':'ARGV_AND_PINNED_PG17_6_CLIENT_STARTUP_SEMANTICS',
            'sourceBootstrapIdentitySha256':sha(canonical(identity)),
            'argv':list(argv),'argvSha256':sha(canonical(argv)),'archiveInputSha256':sha(full),'returnCode':0}


def _extension_compare(source_state, measured, catalog, identity):
    # pg_init_privs is retained in the report, but is not a cross-cluster oracle.
    _extension_state(measured,catalog,identity)
    _require(all(canonical(measured[k])==canonical(source_state[k]) for k in _EXTENSION_ACCEPTANCE),
             'RESTORE_CATALOG_OR_COUNTS_MISMATCH')


def _extension_report(envelope, post_e4, final, catalog, identity, references):
    branch=_extension_prerequisite(envelope,catalog,identity)
    source_state=envelope['extensionState']
    _extension_compare(source_state,post_e4,catalog,identity)
    _extension_compare(source_state,final,catalog,identity)
    _require(references==[],'OWNED_RESTORE_ADMIN_FOOTPRINT')
    return {'profileName':EXTENSION_PROFILE,'profileVersion':EXTENSION_PROFILE_VERSION,'branch':branch,
            'sourceExpectedStateSha256':sha(canonical(source_state)),'querySha256':sha(EXTENSION_SQL.encode()),
            'postE4State':copy.deepcopy(post_e4),'postE4StateSha256':sha(canonical(post_e4)),
            'finalState':copy.deepcopy(final),'finalStateSha256':sha(canonical(final)),
            'ownersExact':True,'rawAclExact':True,'expandedAclExact':True,'effectiveExact':True,
            'structureExact':True,'footprintZero':True}


def _validate_extension_receipt(restore, provenance, catalog, identity, full):
    _require(set(restore)==_RESTORE_FIELDS)
    envelope=provenance['sourceRestorePrerequisites']['extensionRecoveryExpectedState']
    branch=_extension_prerequisite(envelope,catalog,identity)
    context=restore['restoreExecutionContext'];report=restore['extensionValidation']
    _require(type(context) is dict and type(report) is dict and type(context.get('returnCode')) is int and
             type(context.get('profileVersion')) is int and type(report.get('profileVersion')) is int)
    argv=context['argv']
    _require(canonical(context)==canonical(_restore_execution_context(argv,full,branch,identity)))
    expected=_extension_report(envelope,report['postE4State'],report['finalState'],catalog,identity,restore['footprint'])
    _require(canonical(report)==canonical(expected))


def _database_acl_shape(state):
    code = 'DATABASE_ACL_QUERY_RESPONSE_INVALID'
    _require(type(state) is dict and set(state) == {'name','owner','aclRaw','effectiveAcl'}, code)
    _require(type(state['name']) is str and type(state['owner']) is str and
             (state['aclRaw'] is None or type(state['aclRaw']) is str) and type(state['effectiveAcl']) is list, code)
    _require(all(type(row) is list and len(row) == 4 and all(type(v) is str for v in row[:3]) and
                 type(row[3]) is bool for row in state['effectiveAcl']), code)
    return state


def _database_acl_profile(state, identity, roles):
    """Finite source domain. Preserve the original raw ACL and expanded order."""
    _database_acl_shape(state)
    code = 'SOURCE_DATABASE_ACL_PROFILE_UNSUPPORTED'
    _require(type(identity) is dict and type(identity.get('bootstrapOid')) is int and
             identity['bootstrapOid'] == 10 and type(identity.get('serverVersionNum')) is int and
             identity['serverVersionNum'] == 170006, code)
    owner = identity.get('bootstrapName')
    _require(type(owner) is str and re.fullmatch(r'[a-z_][a-z0-9_]{0,62}',owner) and
             owner != OWNED_RESTORE_ADMIN and state['name'] == 'postgres' and state['owner'] == owner, code)
    _role_rows(roles)
    names = [r[0] for r in roles]
    _require(owner in names and OWNED_RESTORE_ADMIN not in names and 'PUBLIC' not in names, code)
    extras = []; raw = state['aclRaw']
    if raw is not None:
        prefix = '{=Tc/'+owner+','+owner+'=CTc/'+owner+','
        _require(raw.startswith(prefix) and raw.endswith('}'), code)
        suffix = raw[len(prefix):-1].split(',')
        _require(1 <= len(suffix) <= 2, code)
        for item in suffix:
            match = re.fullmatch(r'([a-z_][a-z0-9_]{0,62})=C/'+re.escape(owner),item)
            _require(match is not None, code)
            grantee = match[1]
            _require(grantee in names and grantee not in [owner,OWNED_RESTORE_ADMIN] and grantee not in extras, code)
            extras.append(grantee)
    defaults = [[owner,'PUBLIC','CONNECT',False],[owner,'PUBLIC','TEMPORARY',False],
                [owner,owner,'CONNECT',False],[owner,owner,'CREATE',False],[owner,owner,'TEMPORARY',False]]
    wanted = defaults + [[owner,g,'CREATE',False] for g in extras]
    # Sorting is solely a membership check; neither source nor persisted order changes.
    _require(sorted(state['effectiveAcl']) == sorted(wanted) and
             len(state['effectiveAcl']) == len({tuple(r) for r in state['effectiveAcl']}), code)
    baseline = {'name':state['name'],'owner':owner,'aclRaw':None,
                'effectiveAcl':[copy.deepcopy(r) for r in state['effectiveAcl'] if r in defaults]}
    return {'branch':'NULL_DEFAULT' if raw is None else 'OWNER_CREATE_APPEND',
            'orderedGrantees':extras,'baseline':baseline}


def _database_acl_sql(state, identity, roles):
    profile = _database_acl_profile(state,identity,roles)
    if profile['branch'] == 'NULL_DEFAULT': return b''
    lines = ['SET ROLE '+_restore_identifier(identity['bootstrapName'])+';',
             "SELECT pg_catalog.jsonb_build_object('session_user',session_user,'current_user',current_user,'database',pg_catalog.current_database());"]
    lines += ['GRANT CREATE ON DATABASE "postgres" TO '+_restore_identifier(g)+';' for g in profile['orderedGrantees']]
    return ('\n'.join(lines+['RESET ROLE;'])+'\n').encode('ascii')


def _database_acl_plan(state, identity, roles, provenance_sha, archive_sha):
    profile = _database_acl_profile(state,identity,roles)
    raw = _database_acl_sql(state,identity,roles)
    return dict(profile,profileName=DATABASE_ACL_PROFILE,profileVersion=DATABASE_ACL_PROFILE_VERSION,
        sourceState=copy.deepcopy(state),sourceStateSha256=sha(canonical(state)),
        sourceBootstrapProvenanceSha256=provenance_sha,sourceBootstrapIdentitySha256=sha(canonical(identity)),
        archiveInputSha256=archive_sha,derivedSql=raw.decode('ascii'),derivedSqlBytes=len(raw),derivedSqlSha256=sha(raw))


def _database_acl_replay(t, plan):
    """One source-derived batch after E6. A failed batch is not a rollback claim."""
    read = 'BEGIN READ ONLY;\n'+DATABASE_ACL_SQL+'\nROLLBACK;\n'
    before = _database_acl_shape(t._json(read,'OWNED_DATABASE_ACL_STATE'))
    _require(canonical(before) == canonical(plan['baseline']), 'DESTINATION_DATABASE_ACL_BASELINE_MISMATCH')
    raw = plan['derivedSql'].encode('ascii')
    _require(len(raw) == plan['derivedSqlBytes'] and sha(raw) == plan['derivedSqlSha256'], 'DATABASE_ACL_STDIN_SHA_MISMATCH')
    execution = dict(executionCount=0,actualStdinSha256=None,returnCode=None,executionIdentity=None)
    if raw:
        execution.update(executionCount=1,actualStdinSha256=sha(raw))
        try: output = t._sql(raw,'OWNED_DATABASE_ACL_SQL')
        except Failure as error:
            raise Failure('BACKUP_FAILED','DATABASE_ACL_REPLAY_FAILED') from error
        execution['returnCode'] = 0
        try: execution['executionIdentity'] = strict_json(output)
        except Failure as error:
            raise Failure('BACKUP_FAILED','DATABASE_ACL_EXECUTION_IDENTITY_MISMATCH') from error
        _require(execution['executionIdentity'] == {'session_user':OWNED_RESTORE_ADMIN,
                 'current_user':plan['sourceState']['owner'],'database':'postgres'}, 'DATABASE_ACL_EXECUTION_IDENTITY_MISMATCH')
    after = _database_acl_shape(t._json(read,'OWNED_DATABASE_ACL_STATE'))
    _require(canonical(after) == canonical(plan['sourceState']), 'DATABASE_ACL_FIDELITY_MISMATCH')
    return dict(execution,beforeState=before,afterState=after)


def _database_acl_report(plan, execution, final):
    _database_acl_shape(final)
    _require(canonical(execution['beforeState']) == canonical(plan['baseline']), 'DESTINATION_DATABASE_ACL_BASELINE_MISMATCH')
    _require(canonical(execution['afterState']) == canonical(final) == canonical(plan['sourceState']), 'DATABASE_ACL_FIDELITY_MISMATCH')
    mutate = plan['branch'] == 'OWNER_CREATE_APPEND'
    wanted = {'executionCount':int(mutate),'actualStdinSha256':plan['derivedSqlSha256'] if mutate else None,
              'returnCode':0 if mutate else None,'executionIdentity':{'session_user':OWNED_RESTORE_ADMIN,
              'current_user':plan['sourceState']['owner'],'database':'postgres'} if mutate else None}
    _require(canonical({k:execution[k] for k in wanted}) == canonical(wanted), 'DATABASE_ACL_RECEIPT_BINDING_MISMATCH')
    _require(all(OWNED_RESTORE_ADMIN not in row[:2] for row in final['effectiveAcl']), 'DATABASE_ACL_FIDELITY_MISMATCH')
    result = {k:copy.deepcopy(v) for k,v in plan.items() if k != 'baseline'}
    result.update(copy.deepcopy(execution),grantCount=len(plan['orderedGrantees']),finalState=copy.deepcopy(final),
        beforeStateSha256=sha(canonical(execution['beforeState'])),afterStateSha256=sha(canonical(execution['afterState'])),
        finalStateSha256=sha(canonical(final)),baselineExact=True,rawExact=True,expandedExact=True,
        typedTransportFootprintZero=True,status='PASS')
    return result


def _validate_database_acl_receipt(restore, provenance, catalog, identity, full, provenance_sha):
    code = 'DATABASE_ACL_RECEIPT_BINDING_MISMATCH'
    try:
        source = provenance['sourceRestorePrerequisites']['databaseAclBeforeCapture']
        plan = _database_acl_plan(source,identity,catalog['roles'],provenance_sha,sha(full))
        report = restore['databaseAclRecovery']
        execution = {k:report[k] for k in ['beforeState','afterState','executionCount',
                     'actualStdinSha256','returnCode','executionIdentity']}
        expected = _database_acl_report(plan,execution,report['finalState'])
        _require(canonical(report) == canonical(expected), code)
        stage = restore['stagedPlpgsqlValidation']
        _require(canonical(stage['databaseBefore']) == canonical(stage['databaseAfter']) == canonical(plan['baseline']), code)
        _require(restore['phaseResults']['E6_DB_ACL'] == 'PASS' and
                 report['archiveInputSha256'] == restore['restoreExecutionContext']['archiveInputSha256'] and
                 report['sourceBootstrapProvenanceSha256'] == restore['sourceBootstrapProvenanceSha256'] and
                 report['sourceBootstrapIdentitySha256'] == restore['sourceBootstrapIdentitySha256'], code)
    except (Failure,KeyError,TypeError,ValueError,IndexError) as error:
        raise Failure('BACKUP_FAILED',code) from error


def _measure_prerequisites(session, phase, proof):
    values = {}; bindings = []; extra = {}
    for key, query in _prerequisite_queries():
        value = _read_json(session, query)
        if key == 'plpgsqlExpectedState': value = _plpgsql_profile(value)
        if key == 'unsupportedRoleFamilies': _unsupported_families(value)
        if key.startswith('extensionRecoveryExpectedState.'):
            extra[key.split('.')[1]] = value
        else: values[key] = value
        bindings.append({'key':key,'phase':phase,'querySha256':sha(query.encode()),
                         'canonicalResponse':value,'canonicalResponseSha256':sha(canonical(value)),
                         'transportProofRef':_proof_ref('exporter' if phase == 'PRE' else 'afterObservation', proof)})
    values['extensionRecoveryExpectedState'] = _extension_envelope(extra['extensionState'],extra['archiveAclContextGuard'])
    return values, bindings


def _build_provenance(pre, post, before_values, after_values, query_bindings, expected, roles, proofs, context):
    _require(canonical(pre['canonicalResponse']) == canonical(post['canonicalResponse']), 'SOURCE_BOOTSTRAP_DRIFT')
    _require(canonical(before_values) == canonical(after_values), 'SOURCE_BOOTSTRAP_DRIFT')
    response = pre['canonicalResponse']; identity = _identity(response)
    _database_acl_profile(before_values['databaseAclBeforeCapture'],identity,expected['roles'])
    _extension_prerequisite(before_values['extensionRecoveryExpectedState'],expected,identity)
    row = response['bootstrapRows'][0]
    _require([x for x in expected['roles'] if x[0] == identity['bootstrapName']] == [row['roleTuple']], 'SOURCE_BOOTSTRAP_DRIFT')
    rp = proofs['roles']['proof']
    _require(pre['completedAt'] <= rp['startedAt'] <= rp['completedAt'] <= post['startedAt'],
             'SOURCE_BOOTSTRAP_CAPTURE_BINDING_MISMATCH')
    return dict(context, contract=PROVENANCE_CONTRACT, schemaVersion=PROVENANCE_SCHEMA_VERSION,
        recoveryCandidateName=RECOVERY_CANDIDATE, recoveryCandidateVersion=RECOVERY_VERSION,
        transportProofRef={k:_proof_ref(k,proofs[k]) for k in ['exporter','roles','afterObservation']},
        serverVersion=response['serverVersion'], serverVersionNum=response['serverVersionNum'],
        serverEncoding=response['serverEncoding'], clientEncoding=response['clientEncoding'],
        bootstrapOid=10, bootstrapName=identity['bootstrapName'], bootstrapRoleAttributes=row['roleTuple'],
        sessionUser=response['session_user'], currentUser=response['current_user'],
        measurementBefore=pre, measurementAfter=post, querySha256=BOOTSTRAP_QUERY_SHA,
        canonicalResultSha256=sha(canonical({'before':response,'after':post['canonicalResponse']})),
        rawRolesSha256=sha(roles), rawRolesBytes=len(roles), rolesToolInvocationId=rp['invocationId'],
        rolesToolProofSha256=proofs['roles']['sha256'], sourceRestorePrerequisites=dict(before_values,
            sourceCatalogSha256=fingerprint(expected), sourceRolesSha256=sha(canonical(expected['roles'])),
            sourceMembershipsSha256=sha(canonical(expected['memberships'])), queryBindings=query_bindings))


def _validate_provenance(p, expected, roles, bundle, *, authorization_sha=None, package_digest=None):
    try:
        _require(type(p) is dict and set(p) == _PROVENANCE_FIELDS, 'SOURCE_BOOTSTRAP_PROVENANCE_INVALID')
        _require(p['contract'] == PROVENANCE_CONTRACT and type(p['schemaVersion']) is int and p['schemaVersion'] == PROVENANCE_SCHEMA_VERSION)
        _require(p['recoveryCandidateName'] == RECOVERY_CANDIDATE and type(p['recoveryCandidateVersion']) is int and p['recoveryCandidateVersion'] == RECOVERY_VERSION)
        _require(p['querySha256'] == BOOTSTRAP_QUERY_SHA == sha(BOOTSTRAP_SQL.encode()))
        _require(sha(roles) == p['rawRolesSha256'] and len(roles) == p['rawRolesBytes'], 'SOURCE_BOOTSTRAP_CAPTURE_BINDING_MISMATCH')
        _source_collision(expected)
        records = bundle['records']
        for k in ['exporter','roles','afterObservation']:
            ref = _proof_ref(k, records[k]); q = records[k]['proof']
            _require(p['transportProofRef'][k] == ref and q['backupAttempt'] == p['captureId'] == bundle['backupAttempt'] and
                     q['targetIdentitySha256'] == p['sourceTargetId'] == p['sourceIdentitySha256'] and q['targetProfile'] == p['targetProfile'], 'SOURCE_BOOTSTRAP_CAPTURE_BINDING_MISMATCH')
            if q['fixture'] is not True:
                _require(q['authorizationSha256'] == p['authorizationSha256'] and
                         sha(canonical(q['packageHashes'])) == p['operationalPackageDigest'], 'SOURCE_BOOTSTRAP_CAPTURE_BINDING_MISMATCH')
        if authorization_sha is not None: _require(p['authorizationSha256'] == authorization_sha)
        if package_digest is not None: _require(p['operationalPackageDigest'] == package_digest)
        pre,post = p['measurementBefore'],p['measurementAfter']
        for m,key,phase,seq in [(pre,'exporter','PRE',1),(post,'afterObservation','POST',2)]:
            _require(type(m) is dict and set(m) == {
                'phase','measuredAtUtc','startedAt','completedAt','monotonicSequence','querySha256',
                'canonicalResponse','canonicalResponseSha256','rawBootstrapOid','rawBootstrapOidType',
                'normalizedBootstrapOid','transportProofRef','sourceIdentitySha256','captureId',
                'rawResponseAvailable','rawResponseSha256'})
            response = m['canonicalResponse']; _identity(response); row = response['bootstrapRows'][0]
            _require(m['phase'] == phase and type(m['monotonicSequence']) is int and m['monotonicSequence'] == seq and
                     m['querySha256'] == BOOTSTRAP_QUERY_SHA and m['canonicalResponseSha256'] == sha(canonical(response)) and
                     m['transportProofRef'] == p['transportProofRef'][key] and m['captureId'] == p['captureId'] and
                     m['sourceIdentitySha256'] == p['sourceIdentitySha256'] and m['rawResponseAvailable'] is False and m['rawResponseSha256'] is None)
            _require(type(m['rawBootstrapOid']) is type(row['bootstrapOid']) and
                     _bootstrap_oid(m['rawBootstrapOid']) == 10 and m['rawBootstrapOid'] == row['bootstrapOid'] and
                     m['rawBootstrapOidType'] == type(row['bootstrapOid']).__name__ and
                     type(m['normalizedBootstrapOid']) is int and m['normalizedBootstrapOid'] == _bootstrap_oid(row['bootstrapOid']))
            _require(type(m['startedAt']) in (float,int) and type(m['completedAt']) in (float,int) and m['startedAt'] <= m['completedAt'])
            datetime.datetime.fromisoformat(m['measuredAtUtc'])
        values = p['sourceRestorePrerequisites']
        _require(set(values) == {'plpgsqlExpectedState','databaseAclBeforeCapture','unsupportedRoleFamilies','extensionRecoveryExpectedState',
                                'sourceCatalogSha256','sourceRolesSha256','sourceMembershipsSha256','queryBindings'})
        _plpgsql_profile(values['plpgsqlExpectedState']); _unsupported_families(values['unsupportedRoleFamilies'])
        _database_acl_profile(values['databaseAclBeforeCapture'],_identity(pre['canonicalResponse']),expected['roles'])
        _require(values['sourceCatalogSha256'] == fingerprint(expected) and values['sourceRolesSha256'] == sha(canonical(expected['roles'])) and
                 values['sourceMembershipsSha256'] == sha(canonical(expected['memberships'])))
        queries = dict(_prerequisite_queries())
        qb = values['queryBindings']; _require(type(qb) is list and len(qb) == 10)
        _require([(x['phase'],x['key']) for x in qb] == [(phase,k) for phase in ['PRE','POST'] for k in queries])
        for x in qb:
            _require(set(x) == {'key','phase','querySha256','canonicalResponse','canonicalResponseSha256','transportProofRef'})
            _require(x['querySha256'] == sha(queries[x['key']].encode()) and canonical(x['canonicalResponse']) == canonical(_prerequisite_value(values,x['key'])) and
                     x['canonicalResponseSha256'] == sha(canonical(x['canonicalResponse'])) and
                     x['transportProofRef'] == p['transportProofRef']['exporter' if x['phase'] == 'PRE' else 'afterObservation'])
        rp = records['roles']['proof']
        _require(rp['outputSha256'] == p['rawRolesSha256'] and rp['invocationId'] == p['rolesToolInvocationId'] and
                 records['roles']['sha256'] == p['rolesToolProofSha256'])
        context = {k:p[k] for k in ['captureId','sourceTargetId','targetProfile','sourceIdentitySha256','authorizationSha256','operationalPackageDigest']}
        measured = {k:values[k] for k in ['plpgsqlExpectedState','databaseAclBeforeCapture','unsupportedRoleFamilies','extensionRecoveryExpectedState']}
        rebuilt = _build_provenance(pre,post,measured,measured,qb,expected,roles,records,context)
        _require(canonical(rebuilt) == canonical(p), 'SOURCE_BOOTSTRAP_CAPTURE_BINDING_MISMATCH')
        return _identity(pre['canonicalResponse'])
    except Failure: raise
    except (KeyError,TypeError,ValueError,IndexError):
        raise Failure('BACKUP_FAILED','SOURCE_BOOTSTRAP_PROVENANCE_INVALID') from None


def _without_admin(state, references):
    _role_rows(state['roles'])
    _require([r for r in state['roles'] if r[0] == OWNED_RESTORE_ADMIN] == [OWNED_RESTORE_ADMIN_TUPLE], 'OWNED_RESTORE_ADMIN_IDENTITY')
    _require(references == [], 'OWNED_RESTORE_ADMIN_FOOTPRINT')
    _require(not any(OWNED_RESTORE_ADMIN in row[:3] for row in state['memberships']), 'OWNED_RESTORE_ADMIN_MEMBERSHIP_FOOTPRINT')
    # Additional direct positions are checked even if a malformed SQL receipt says zero.
    for family,index in [('relations',3),('namespaces',1),('extensions',3),('types',3),('defaults',0)]:
        _require(all(row[index] != OWNED_RESTORE_ADMIN for row in state.get(family,[])), 'OWNED_RESTORE_ADMIN_FOOTPRINT')
    _require(all(x['owner'] != OWNED_RESTORE_ADMIN for x in state.get('functions',[])), 'OWNED_RESTORE_ADMIN_FOOTPRINT')
    _require(all(OWNED_RESTORE_ADMIN not in x[5] for x in state.get('policies',[])), 'OWNED_RESTORE_ADMIN_FOOTPRINT')
    _require(all(x.get('grantor') != OWNED_RESTORE_ADMIN and x.get('grantee') != OWNED_RESTORE_ADMIN for x in state.get('targetAcl',[])), 'OWNED_RESTORE_ADMIN_FOOTPRINT')
    _require(state.get('ledgerDescriptor',{}).get('owner') != OWNED_RESTORE_ADMIN, 'OWNED_RESTORE_ADMIN_FOOTPRINT')
    normalized = copy.deepcopy(state)
    normalized['roles'] = [r for r in normalized['roles'] if r[0] != OWNED_RESTORE_ADMIN]
    return normalized


def _role_gate(actual, expected):
    _source_collision(expected)
    normalized = _without_admin(actual, [])
    for row in actual['memberships']:
        _require(type(row) is list and len(row) == 6 and all(type(v) is bool for v in row[3:]), 'OWNED_ROLE_REPLAY_INCOMPLETE')
    wanted = {k:expected[k] for k in ['roles','memberships']}
    _require(canonical({k:normalized[k] for k in wanted}) == canonical(wanted), 'OWNED_ROLE_REPLAY_INCOMPLETE')
    return sha(canonical(wanted))


class OwnedRestoreDestinationCluster:
    """One destination attempt, with source-bound bootstrap and separate transport."""
    def __init__(self, source_identity, encoding):
        _restore_identifier(source_identity['bootstrapName']); _bootstrap_oid(source_identity['bootstrapOid'])
        _require(encoding in ('UTF8','SQL_ASCII') and source_identity['serverVersionNum'] == 170006, 'SOURCE_RECOVERY_PROFILE_UNSUPPORTED')
        self.name = 'uply-runner-i1-' + uuid.uuid4().hex
        self.closed = False
        try:
            with _diagnostic_phase('E1'), _diagnostic_operation('OWNED_CLUSTER_RUN',self.name):
                _docker(['run','--rm','-d','--pull=never','--network','none','--name',self.name,
                         '--label','uply.task=runner-i1','--read-only','--tmpfs','/tmp:rw,size=2048m,mode=1777',
                         '--user','100:101','--entrypoint','/bin/sh',IMAGE_ID,'-c',
                         'initdb -D /tmp/pg -A trust --no-locale -U "$1" -E "$2" >/tmp/init.log && exec postgres -D /tmp/pg -k /tmp -c listen_addresses=\'\' -c max_connections=30',
                         'owned-restore-init',source_identity['bootstrapName'],encoding])
            with _diagnostic_phase('E2'):
                for _ in range(100):
                    try:
                        with _diagnostic_operation('OWNED_PG_ISREADY',self.name):
                            _docker(['exec',self.name,'pg_isready','-h','/tmp','-U',source_identity['bootstrapName'],'-d','postgres'])
                        break
                    except Failure: time.sleep(0.1)
                else: raise Failure('BACKUP_FAILED','OWNED_DB_START')
                self.transport = OwnedRestoreDestinationTransport(self.name)
                response = self.transport._json(BOOTSTRAP_SQL,'OWNED_BOOTSTRAP_IDENTITY',bootstrap_user=source_identity['bootstrapName'])
                self.bootstrap_identity = _identity(response)
                _require(self.bootstrap_identity == source_identity and response['session_user'] == source_identity['bootstrapName'] and
                         response['current_user'] == source_identity['bootstrapName'] and response['serverEncoding'] == encoding,
                         'DESTINATION_BOOTSTRAP_IDENTITY_MISMATCH')
                sql = 'CREATE ROLE '+_restore_identifier(OWNED_RESTORE_ADMIN)+' SUPERUSER INHERIT CREATEROLE CREATEDB LOGIN REPLICATION BYPASSRLS CONNECTION LIMIT -1;'
                self.transport._sql(sql.encode(),'OWNED_RESTORE_ADMIN_CREATE',bootstrap_user=source_identity['bootstrapName'])
                response = self.transport._json(BOOTSTRAP_SQL,'OWNED_RESTORE_ADMIN_IDENTITY')
                _require(_identity(response) == source_identity and response['session_user'] == OWNED_RESTORE_ADMIN and
                         response['current_user'] == OWNED_RESTORE_ADMIN, 'OWNED_RESTORE_ADMIN_IDENTITY')
                state = self.transport._json(ROLE_STATE_SQL,'OWNED_RESTORE_ADMIN_IDENTITY')
                _without_admin(state, [])
                self.transport_identity = response
        except BaseException as error:
            _close_preserving(self.close,error)
            raise

    def close(self):
        if not self.closed:
            with _diagnostic_phase('E9'):
                OwnedRestoreDestinationTransport(self.name)._inspect()
                with _diagnostic_operation('OWNED_STOP',self.name):
                    _docker(['stop','--time','2',self.name]); self.closed = True
                for _ in range(50):
                    with _diagnostic_operation('OWNED_REMOVAL_CHECK',self.name):
                        if not _docker(['ps','-aq','--filter','name=^/'+self.name+'$']).strip(): break
                    time.sleep(0.1)
                else: raise Failure('BACKUP_FAILED','CLEANUP_FAILED')

    def __enter__(self): return self
    def __exit__(self,kind,error,traceback): _close_preserving(self.close,error)


def _staged_plpgsql(t, expected, prerequisites):
    wanted = _plpgsql_profile(prerequisites['plpgsqlExpectedState'])
    owner = wanted['extensions'][0][3]
    final = [row for row in expected['roles'] if row[0] == owner]
    _require(len(final) == 1, 'SOURCE_RECOVERY_PROFILE_UNSUPPORTED')
    original = final[0]
    before = t._json(DATABASE_ACL_SQL,'OWNED_STAGED_PLPGSQL_STATE')
    if original[1] is False:
        t._sql(('ALTER ROLE '+_restore_identifier(owner)+' SUPERUSER;').encode(),'OWNED_STAGED_PLPGSQL_SQL')
    # Each one-shot invocation uses strict ON_ERROR_STOP; no transaction assumption.
    try:
        t._sql(b'DROP EXTENSION plpgsql RESTRICT;','OWNED_STAGED_PLPGSQL_SQL')
    except Failure as error:
        raise Failure('BACKUP_FAILED','STAGED_PLPGSQL_DEPENDENCY') from error
    t._sql(('SET ROLE '+_restore_identifier(owner)+"; CREATE EXTENSION plpgsql WITH SCHEMA pg_catalog VERSION '1.0'; RESET ROLE;").encode(),'OWNED_STAGED_PLPGSQL_SQL')
    if original[1] is False:
        t._sql(('ALTER ROLE '+_restore_identifier(owner)+' NOSUPERUSER;').encode(),'OWNED_STAGED_PLPGSQL_SQL')
    actual = _plpgsql_profile(t._json(PLPGSQL_SQL,'OWNED_STAGED_PLPGSQL_STATE'))
    after = t._json(DATABASE_ACL_SQL,'OWNED_STAGED_PLPGSQL_STATE')
    role_hash = _role_gate(t._json(ROLE_STATE_SQL,'OWNED_ROLE_STATE'),expected)
    refs = t._json(FOOTPRINT_SQL,'OWNED_FOOTPRINT')
    _require(canonical(actual) == canonical(wanted) and canonical(before) == canonical(after) and refs == [], 'STAGED_PLPGSQL_FINALIZATION_FAILED')
    return {'status':'PASS','strategy':'STAGED','owner':owner,'temporaryPrivilegeUsed':not original[1],
            'finalOwnerTuple':original,'finalizationExact':True,'extensionExpected':wanted,'extensionActual':actual,
            'extensionSha256':sha(canonical(actual)),'databaseBefore':before,'databaseAfter':after,
            'databaseAclRawPreserved':True,'databaseAclEffectivePreserved':True,'footprint':refs,
            'roleFamilySha256':role_hash}


def _acl_supplement(expected, restored):
    # Object names keep existing quoting; the ASCII restriction is for roles.
    qi = lambda value: '"'+value.replace('"','""')+'"'
    supplement = []
    for old,new in zip(expected['relations'],restored['relations']):
        if old!=new and old[:4]==new[:4] and old[5:]==new[5:] and new[4] is None:
            owner=old[3];priv='rwU' if old[2]=='S' else 'arwdDxtm'
            if old[4]==[owner+'='+priv+'/'+owner]:
                supplement.append('SET ROLE '+qi(owner)+'; GRANT ALL ON '+('SEQUENCE' if old[2]=='S' else 'TABLE')+' '+qi(old[0])+'.'+qi(old[1])+' TO '+qi(owner)+'; RESET ROLE;')
    for old,new in zip(expected['namespaces'],restored['namespaces']):
        if old[:2]==new[:2] and new[2] is None and old[2]==[old[1]+'=UC/'+old[1]]:
            supplement.append('SET ROLE '+qi(old[1])+'; GRANT ALL ON SCHEMA '+qi(old[0])+' TO '+qi(old[1])+'; RESET ROLE;')
    return supplement


def _restore(full,roles,expected,counts,provenance,bundle):
    source_identity = _validate_provenance(provenance,expected,roles,bundle)
    provenance_sha = sha(canonical(provenance)+b'\n')
    extension_expected = provenance['sourceRestorePrerequisites']['extensionRecoveryExpectedState']
    branch = _extension_prerequisite(extension_expected,expected,source_identity)
    database_plan = _database_acl_plan(provenance['sourceRestorePrerequisites']['databaseAclBeforeCapture'],
                                       source_identity,expected['roles'],provenance_sha,sha(full))
    with OwnedRestoreDestinationCluster(source_identity,provenance['serverEncoding']) as cluster:
        t = cluster.transport
        with _diagnostic_phase('E3'):
            derived, derivation = _derive_roles(roles,source_identity,cluster.bootstrap_identity)
            derivation.update(sourceBootstrapProvenanceSha256=provenance_sha,
                              destinationIdentitySha256=sha(canonical(cluster.bootstrap_identity)))
            actual_stdin_sha = sha(derived)
            _require(actual_stdin_sha == derivation['derivedSha256'], 'ROLE_STDIN_SHA_MISMATCH')
            t._sql(derived,'OWNED_ROLES_SQL')
            derivation['actualStdinSha256'] = actual_stdin_sha
            post_e3 = _role_gate(t._json(ROLE_STATE_SQL,'OWNED_ROLE_STATE'),expected)
            stage = _staged_plpgsql(t,expected,provenance['sourceRestorePrerequisites'])
            _require(canonical(stage['databaseBefore']) == canonical(stage['databaseAfter']) == canonical(database_plan['baseline']),
                     'DESTINATION_DATABASE_ACL_BASELINE_MISMATCH')
        with _diagnostic_phase('E4'), _diagnostic_operation('OWNED_PG_RESTORE',cluster.name):
            restore_argv = _restore_argv(cluster.name,branch,source_identity)
            _docker(restore_argv,full,300)
            execution_context = _restore_execution_context(restore_argv,full,branch,source_identity)
        with _diagnostic_phase('E5'):
            with t._session(True) as session:
                restored=observe(session)
                extension_e5=_read_json(session,EXTENSION_SQL)
                session._rollback()
            _extension_compare(extension_expected['extensionState'],extension_e5,expected,source_identity)
        supplement = _acl_supplement(expected,restored)
        with _diagnostic_phase('E6',required=bool(supplement)):
            if supplement: t._sql('\n'.join(supplement).encode(),'OWNED_SUPPLEMENT_SQL')
        with _diagnostic_phase('E6_DB_ACL'):
            database_execution = _database_acl_replay(t,database_plan)
        with _diagnostic_phase('E7'):
            with t._session(True) as session:
                restored=observe(session);rc=_counts(session)
                extension_e7=_read_json(session,EXTENSION_SQL)
                database_final=_database_acl_shape(_read_json(session,DATABASE_ACL_SQL))
                session._rollback()
            ext = _plpgsql_profile(t._json(PLPGSQL_SQL,'OWNED_STAGED_PLPGSQL_STATE'))
            refs = t._json(FOOTPRINT_SQL,'OWNED_FOOTPRINT')
            _unsupported_families(t._json(UNSUPPORTED_ROLE_FAMILIES_SQL,'OWNED_ROLE_STATE'))
        with _diagnostic_phase('E8'):
            normalized = _without_admin(restored,refs)
            _require(canonical(normalized) == canonical(expected) and canonical(rc) == canonical(counts) and
                     canonical(ext) == canonical(stage['extensionExpected']),
                     'RESTORE_CATALOG_OR_COUNTS_MISMATCH')
            final_role_hash = _role_gate(restored,expected)
            extension_report = _extension_report(extension_expected,extension_e5,extension_e7,expected,source_identity,refs)
            database_report = _database_acl_report(database_plan,database_execution,database_final)
            result = {'contract':RESTORE_CONTRACT,'recoveryContractVersion':RECOVERY_VERSION,
                'recoveryCandidateName':RECOVERY_CANDIDATE,'status':'PASS',
                'sourceBootstrapProvenanceSha256':provenance_sha,
                'sourceBootstrapIdentitySha256':sha(canonical(source_identity)),
                'destinationBootstrapIdentitySha256':sha(canonical(cluster.bootstrap_identity)),
                'restoreTransportIdentitySha256':sha(canonical(cluster.transport_identity)),
                'sourceBootstrapIdentity':source_identity,'destinationBootstrapIdentity':cluster.bootstrap_identity,
                'restoreTransportIdentity':cluster.transport_identity,'transportTuple':list(OWNED_RESTORE_ADMIN_TUPLE),
                'rolesDerivationReceipt':derivation,'postE3RoleFamilySha256':post_e3,
                'postFinalizationRoleFamilySha256':stage['roleFamilySha256'],
                'finalRoleFamilySha256':final_role_hash,'stagedPlpgsqlValidation':stage,
                'restoreAdminNormalized':True,'restoreAdminTrackedFootprintZero':True,'footprint':refs,
                'normalizedCatalogSha256':fingerprint(normalized),'catalogSha256':fingerprint(normalized),
                'countsSha256':sha(canonical(rc)),'ledgerPrefixSha256':normalized['prefix'],
                'network':'none','hostPorts':0,'hostMounts':0,'sourceCredentialsMounted':False,'imageId':IMAGE_ID,
                'databaseOwnerClassification':'LOCAL_RESTORE_INFRASTRUCTURE_ONLY',
                'databaseOwnerSourceFidelityClaim':False,'phaseResults':{k:'PASS' for k in ['E1','E2','E3','E3_RECONCILIATION','E4','E5','E6_DB_ACL','E7','E8']},
                'aclSupplementCount':len(supplement),
                'restoreExecutionContext':execution_context,'extensionValidation':extension_report,
                'databaseAclRecovery':database_report}
            result['phaseResults']['E6'] = 'PASS' if supplement else 'NOT_REQUIRED'
    # Cleanup must have actually completed before this result can be sealed.
    result.update(cleanup='OWNED_CONTAINER_REMOVED',ownedCleanup={'status':'PASS','ownedContainersRemaining':0})
    result['phaseResults']['E9'] = 'PASS'
    return result


def capture_backup(plan,auth,transport,root):
    authorize(plan,auth,'BACKUP_READ_EXPORT')
    if plan.fixture != transport.fixture or transport.identity != auth['targetIdentity']:raise Failure('TARGET_IDENTITY_MISMATCH')
    if not plan.fixture and Path(root)!=Path(transport.profile['backupRoot']):raise Failure('BACKUP_FAILED','BACKUP_ROOT')
    root=private_directory(root)
    directory=private_directory(root/('exact-single-'+uuid.uuid4().hex))
    metadata=private_directory(directory/'metadata')
    started=time.time()
    attempt=uuid.uuid4().hex
    if getattr(transport,'_backup_attempt',None):raise Failure('BACKUP_FAILED','BACKUP_ALREADY_ACTIVE')
    transport._backup_attempt=attempt
    proofs={}
    context={'captureId':attempt,'sourceTargetId':sha(canonical(transport.identity)),
             'targetProfile':plan.data['targetProfile'],'sourceIdentitySha256':sha(canonical(transport.identity)),
             'authorizationSha256':sha(canonical(auth)),'operationalPackageDigest':sha(canonical(auth['packageHashes']))}
    diagnostic=None
    local_finished=False
    try:
        diagnostic_root = root.parent / 'backup-diagnostics' if plan.fixture else ROOT / transport.profile['receiptRoot'] / 'backup-diagnostics'
        diagnostic=_LocalBackupDiagnostics(diagnostic_root, attempt, plan, auth)
        with transport._session(True) as s:
            proofs['exporter']=s._transport_proof
            before=observe(s)
            if fingerprint(before)!=auth['catalogBeforeSha256'] or before['prefix']!=plan.data['ledger']['sourcePrefixSha256']:
                raise Failure('BACKUP_FAILED','BACKUP_BASELINE')
            counts=_counts(s)
            snap=s._json('select to_jsonb(pg_export_snapshot());')
            if not re.fullmatch('[0-9A-F]+-[0-9A-F]+-[0-9]+',snap):raise Failure('BACKUP_FAILED','SNAPSHOT_ID')
            full=transport._tool('pg_dump',['-d','postgres','-Fc','--snapshot='+snap])
            proofs['full']=transport._take_tool_proof('pg_dump',full)
            schema=transport._tool('pg_dump',['-d','postgres','-Fc','--schema-only','--snapshot='+snap])
            proofs['schema']=transport._take_tool_proof('pg_dump',schema)
            _source_collision(before)
            before_values,before_queries=_measure_prerequisites(s,'PRE',proofs['exporter'])
            pre=_measure_bootstrap(s,'PRE',proofs['exporter'],context)
            _require(pre['canonicalResponse']['session_user'] == transport.identity['role'] and
                     pre['canonicalResponse']['current_user'] == transport.identity['currentRole'],
                     'SOURCE_BOOTSTRAP_CAPTURE_BINDING_MISMATCH')
            roles=transport._tool('pg_dumpall',['--roles-only','--no-role-passwords'])
            proofs['roles']=transport._take_tool_proof('pg_dumpall',roles)
            # Exporter must still be alive, and all same-snapshot contracts must match.
            if observe(s)!=before:raise Failure('BACKUP_FAILED','EXPORTER_DRIFT')
            s._rollback()
        with transport._session(True) as s:
            proofs['afterObservation']=s._transport_proof
            post=_measure_bootstrap(s,'POST',proofs['afterObservation'],context)
            after_values,after_queries=_measure_prerequisites(s,'POST',proofs['afterObservation'])
            after=observe(s);s._rollback()
        provenance=_build_provenance(pre,post,before_values,after_values,before_queries+after_queries,before,roles,proofs,context)
        if after!=before:raise Failure('BACKUP_FAILED','SOURCE_OR_ROLE_DRIFT')
        bundle={'contract':'backup-transport-proofs/1','backupAttempt':attempt,
                'snapshot':snap,'records':{k:{'proof':_read_proof(v),'sha256':v['sha256']} for k,v in proofs.items()}}
        _validate_proofs(bundle,plan,auth,transport,started,time.time(),
                         {'full':sha(full),'schema':sha(schema),'roles':sha(roles)})
        _validate_provenance(provenance,before,roles,bundle,authorization_sha=sha(canonical(auth)),
                             package_digest=sha(canonical(auth['packageHashes'])))
        if not full.startswith(b'PGDMP') or not schema.startswith(b'PGDMP'):raise Failure('BACKUP_FAILED','ARCHIVE_FORMAT')
        # Validate both actual archive TOCs with pinned owned tool image.
        with diagnostic.active():
            for phase,kind,raw in [('C','ARCHIVE_FULL_TOC_LIST',full),('D','ARCHIVE_SCHEMA_TOC_LIST',schema)]:
                with _diagnostic_phase(phase), _diagnostic_operation(kind):
                    _docker(['run','--rm','-i','--pull=never','--network','none','--entrypoint','pg_restore',IMAGE_ID,'--list'],raw)
            restore=_restore(full,roles,before,counts,provenance,bundle)
        diagnostic.finish()
        local_finished=True
        for name,raw in [('database.dump',full),('schema.dump',schema),('roles.sql',roles)]:_write_bytes(directory/name,raw)
        exclusive(metadata/'catalog.json',before,redact=False)
        exclusive(metadata/'counts.json',counts,redact=False)
        exclusive(metadata/'migration-ledger.json',before['ledger'],redact=False)
        exclusive(metadata/'bootstrap-provenance.json',provenance,redact=False)
        exclusive(metadata/'restore.json',restore,redact=False)
        # A portable, hash-bound copy of each immutable invocation sidecar. No
        # proof is borrowed from a different client or from an earlier backup.
        bundle={'contract':'backup-transport-proofs/1','backupAttempt':attempt,
                'snapshot':snap,'records':{k:{'proof':_read_proof(v),'sha256':v['sha256']} for k,v in proofs.items()}}
        _validate_proofs(bundle,plan,auth,transport,started,time.time(),
                         {'full':sha(full),'schema':sha(schema),'roles':sha(roles)})
        exclusive(metadata/'transport-proofs.json',bundle)
        files={str(p.relative_to(directory)):{'sha256':sha(safe_file(p,True)),'bytes':p.stat().st_size} for p in directory.rglob('*') if p.is_file()}
        manifest={'reportVersion':MANIFEST_VERSION,'status':'VALID','planId':plan.data['planId'],
                  'backupAttempt':attempt,'snapshot':snap,
                  'transportContract':'OWNED_ISOLATED_FIXTURE' if plan.fixture else TRANSPORT_CONTRACT,
                  'riskAcceptance':None if plan.fixture else RISK_BINDING.copy(),
                  'planSha256':plan.digest,'targetProfile':plan.data['targetProfile'],'sourceIdentitySha256':sha(canonical(transport.identity)),
                  'snapshotStart':started,'snapshotEnd':time.time(),'sealedAt':time.time(),
                  'ledgerCount':len(before['ledger']),'ledgerLatest':before['ledger'][-1]['version'],
                  'ledgerSha256':before['prefix'],'fullSourcePrefixDigest':before['prefix'],
                  'catalogSha256':fingerprint(before),'packageHashes':auth['packageHashes'],'files':files,
                  'rolesCapture':'SEPARATE_NON_MVCC_CAPTURE_BEFORE_AFTER_FINGERPRINT_MATCH',
                  'restoreStatus':'PASS','offHostCopy':'NOT_CLAIMED','retention':'7_DAYS_AND_THROUGH_STABLE_STAGE1G'}
        manifest.update(recoveryCandidateName=RECOVERY_CANDIDATE,recoveryCandidateVersion=RECOVERY_VERSION,
                        recoveryReportContract=RESTORE_CONTRACT,rawRolesSha256=sha(roles),
                        sourceBootstrapProvenance=dict(path=PROVENANCE_PATH,contract=PROVENANCE_CONTRACT,**files[PROVENANCE_PATH]))
        _require(set(files)==REQUIRED_FILES)
        authorize(plan,auth,'BACKUP_READ_EXPORT')
        exclusive(metadata/'manifest.json',manifest)
        _write_bytes(directory/'SHA256SUMS', ''.join(v['sha256']+'  '+k+'\n' for k,v in sorted(files.items())).encode())
        return directory
    except Exception as e:
        wrapped_primary = e.primary if isinstance(e,_DiagnosticPersistenceError) else None
        if wrapped_primary is not None:e=wrapped_primary
        if diagnostic is not None and not local_finished:diagnostic.finish(e)
        if isinstance(e,_DiagnosticPersistenceError):e=Failure('BACKUP_FAILED','DIAGNOSTIC_PERSISTENCE_FAILED')
        try:exclusive(directory/'FAILED.json',{'status':'INVALID','code':e.code if isinstance(e,Failure) else 'CAPTURE_FAILED'})
        except Exception:pass
        if isinstance(e,Failure):
            if wrapped_primary is not None or e.code=='DIAGNOSTIC_PERSISTENCE_FAILED':raise e from None
            raise
        raise Failure('BACKUP_FAILED','CAPTURE_FAILED') from None
    finally:
        transport._backup_attempt=None


def _validate_proofs(bundle,plan,auth,transport,start,end,outputs):
    try:
        risk_guard(plan,auth)
        records=bundle['records'];seen=set();authorities=set()
        if bundle['contract']!='backup-transport-proofs/1' or set(records)!={'exporter','full','schema','roles','afterObservation'}:
            raise ValueError()
        if not re.fullmatch('[a-f0-9]{32}',bundle['backupAttempt']):raise ValueError()
        if not re.fullmatch('[0-9A-F]+-[0-9A-F]+-[0-9]+',bundle['snapshot']):raise ValueError()
        for name,record in records.items():
            p=record['proof'];tool='pg_dumpall' if name=='roles' else ('pg_dump' if name in ('full','schema') else 'psql')
            if (record['sha256']!=sha(canonical(p)+b'\n') or p['fixture'] is not plan.fixture or
                p['tool']!=tool or p['toolImageId']!=IMAGE_ID or
                p['targetProfile']!=plan.data['targetProfile'] or p['backupAttempt']!=bundle['backupAttempt'] or
                p['targetIdentitySha256']!=sha(canonical(transport.identity)) or
                not start<=p['startedAt']<=p['completedAt']<=end or p['invocationId'] in seen or
                not re.fullmatch('[a-f0-9]{32}',p['invocationId'])):raise ValueError()
            seen.add(p['invocationId'])
            if plan.fixture:
                if p['proofKind']!='OWNED_ISOLATED_INVOCATION' or p['riskAcceptance'] is not None:raise ValueError()
            else:
                kind='PSQL_SAME_SESSION_METADATA' if tool=='psql' else 'REAL_INVOCATION_LIBPQ_ENFORCEMENT'
                if (p['proofKind']!=kind or p['transportContract']!=TRANSPORT_CONTRACT or
                    p['riskAcceptance']!=RISK_BINDING or p['packageHashes']!=auth['packageHashes'] or
                    p['sslmode']!='verify-full' or p['gssencmode']!='disable' or
                    p['clientTlsRequired'] is not True or p['clientTls']['enabled'] is not True or
                    p['endpoint']['port']!=5432 or
                    sha(canonical(p['endpoint']['host']))!=transport.identity['hostIdentitySha256'] or
                    p['credentialIdentitySha256']!=auth['credentialIdentitySha256']):raise ValueError()
                authorities.add(p['authorizationSha256'])
            if name in outputs:
                args=(['--roles-only','--no-role-passwords'] if name=='roles' else
                      ['-d','postgres','-Fc']+(['--schema-only'] if name=='schema' else [])+['--snapshot='+bundle['snapshot']])
                if (p['outputSha256']!=outputs[name] or p['dumpKind']!=name or p['exitCode']!=0 or
                    p['inputSha256']!=sha(canonical([tool,args])) or
                    p['snapshot']!=(None if name=='roles' else bundle['snapshot'])):raise ValueError()
        if not plan.fixture and len(authorities)!=1:raise ValueError()
    except (KeyError,ValueError,TypeError,Failure):
        raise Failure('BACKUP_FAILED','BACKUP_CLIENT_TLS_PROOF_MISSING') from None


def validate_recovery_artifacts(path, manifest_sha, *, expected_package_digest,
                                expected_plan_sha, expected_target_sha=None,
                                expected_authorization_sha=None, expected_target_identity=None,
                                expected_credential_sha=None, historical=False):
    """Pure private-file validation. No session, credential, Docker or mutation."""
    try:
        path = Path(path)
        for directory in [path, path/'metadata']:
            s = directory.stat()
            _require(not directory.is_symlink() and stat.S_ISDIR(s.st_mode) and
                     stat.S_IMODE(s.st_mode) == 0o700 and s.st_uid == os.getuid())
        raw = safe_file(path/'metadata/manifest.json',True)
        _require(sha(raw) == manifest_sha)
        m = strict_json(raw)
        _require(m['planSha256'] == expected_plan_sha and m['status'] == 'VALID' and m['restoreStatus'] == 'PASS')
        package_digest = sha(canonical(m['packageHashes']))
        _require(package_digest == expected_package_digest)
        legacy = m['reportVersion'] == 'exact-single-backup/2'
        if legacy:
            _require(historical is True and package_digest == LEGACY_PACKAGE_DIGEST)
        else:
            _require(m['reportVersion'] == MANIFEST_VERSION and m['recoveryCandidateName'] == RECOVERY_CANDIDATE and
                     type(m['recoveryCandidateVersion']) is int and m['recoveryCandidateVersion'] == RECOVERY_VERSION and
                     m['recoveryReportContract'] == RESTORE_CONTRACT)
        required = LEGACY_FILES if legacy else REQUIRED_FILES
        _require(set(m['files']) == required)
        contents = {}
        for n in required:
            entry = m['files'][n]
            _require(set(entry) == {'sha256','bytes'} and type(entry['bytes']) is int)
            contents[n] = safe_file(path/n,True)
            _require(sha(contents[n]) == entry['sha256'] and len(contents[n]) == entry['bytes'])
        _require(contents['database.dump'].startswith(b'PGDMP') and contents['schema.dump'].startswith(b'PGDMP'))
        catalog = strict_json(contents['metadata/catalog.json']); counts = strict_json(contents['metadata/counts.json'])
        restore = strict_json(contents['metadata/restore.json'])
        _require(fingerprint(catalog) == m['catalogSha256'] == restore['catalogSha256'])
        _require(catalog['prefix'] == m['fullSourcePrefixDigest'] == restore['ledgerPrefixSha256'])
        _require(strict_json(contents['metadata/migration-ledger.json']) == catalog['ledger'])
        _require(restore['status'] == 'PASS')
        bundle = strict_json(contents['metadata/transport-proofs.json'])
        _require(bundle['contract'] == 'backup-transport-proofs/1' and
                 bundle['backupAttempt'] == m['backupAttempt'] and bundle['snapshot'] == m['snapshot'])
        records = bundle['records']; seen = set()
        _require(set(records) == {'exporter','full','schema','roles','afterObservation'})
        _require(m['snapshotStart'] <= m['snapshotEnd'] <= m['sealedAt'])
        fixture = m['transportContract'] == 'OWNED_ISOLATED_FIXTURE'
        _require(m['transportContract'] == ('OWNED_ISOLATED_FIXTURE' if fixture else TRANSPORT_CONTRACT) and
                 canonical(m['riskAcceptance']) == canonical(None if fixture else RISK_BINDING))
        if expected_target_identity is not None:
            _require(sha(canonical(expected_target_identity)) == m['sourceIdentitySha256'] and
                     expected_target_identity['fixture'] is fixture)
        authorities = set(); endpoints = set(); credentials = set()
        for key, record in records.items():
            q = record['proof']; _proof_ref(key, record)
            _require(q['backupAttempt'] == m['backupAttempt'] and q['targetIdentitySha256'] == m['sourceIdentitySha256'] and
                     q['targetProfile'] == m['targetProfile'] and q['toolImageId'] == IMAGE_ID and
                     q['invocationId'] not in seen and re.fullmatch('[a-f0-9]{32}', q['invocationId']) and
                     m['snapshotStart'] <= q['startedAt'] <= q['completedAt'] <= m['snapshotEnd'])
            seen.add(q['invocationId'])
            tool = 'pg_dumpall' if key == 'roles' else ('pg_dump' if key in ('full','schema') else 'psql')
            _require(q['tool'] == tool and q['fixture'] is fixture and
                     q['contract'] == 'maintenance-client-proof/1' and q['transportContract'] == m['transportContract'] and
                     canonical(q['riskAcceptance']) == canonical(m['riskAcceptance']))
            if fixture:
                _require(q['proofKind'] == 'OWNED_ISOLATED_INVOCATION')
            else:
                _require(q['proofKind'] == ('PSQL_SAME_SESSION_METADATA' if tool == 'psql' else 'REAL_INVOCATION_LIBPQ_ENFORCEMENT') and
                         canonical(q['packageHashes']) == canonical(m['packageHashes']) and
                         q['sslmode'] == 'verify-full' and q['gssencmode'] == 'disable' and
                         q['clientTlsRequired'] is True and q['clientTls']['enabled'] is True and
                         type(q['endpoint']['port']) is int and q['endpoint']['port'] == 5432)
                authorities.add(q['authorizationSha256']); credentials.add(q['credentialIdentitySha256'])
                endpoints.add(sha(canonical(q['endpoint'])))
                if expected_target_identity is not None:
                    _require(sha(canonical(q['endpoint']['host'])) == expected_target_identity['hostIdentitySha256'])
                if expected_credential_sha is not None:
                    _require(q['credentialIdentitySha256'] == expected_credential_sha)
                if expected_authorization_sha is not None:
                    _require(q['authorizationSha256'] == expected_authorization_sha)
            if key in ('full','schema','roles'):
                artifact = {'full':'database.dump','schema':'schema.dump','roles':'roles.sql'}[key]
                args = (['--roles-only','--no-role-passwords'] if key == 'roles' else
                        ['-d','postgres','-Fc']+(['--schema-only'] if key == 'schema' else [])+['--snapshot='+m['snapshot']])
                _require(q['outputSha256'] == m['files'][artifact]['sha256'] and q['exitCode'] == 0 and
                         q['dumpKind'] == key and q['inputSha256'] == sha(canonical([tool,args])) and
                         q['snapshot'] == (None if key == 'roles' else m['snapshot']))
        if not fixture: _require(len(authorities) == len(endpoints) == len(credentials) == 1)
        if expected_target_sha is not None: _require(m['sourceIdentitySha256'] == expected_target_sha)
        if legacy: return m
        _require(restore['contract'] == RESTORE_CONTRACT and type(restore['recoveryContractVersion']) is int and
                 restore['recoveryContractVersion'] == RECOVERY_VERSION and restore['recoveryCandidateName'] == RECOVERY_CANDIDATE)
        prov = strict_json(contents[PROVENANCE_PATH]); prov_sha = sha(contents[PROVENANCE_PATH])
        _require(contents[PROVENANCE_PATH] == canonical(prov)+b'\n')
        _require(m['sourceBootstrapProvenance'] == dict(path=PROVENANCE_PATH,contract=PROVENANCE_CONTRACT,**m['files'][PROVENANCE_PATH]) and
                 m['rawRolesSha256'] == m['files']['roles.sql']['sha256'])
        identity = _validate_provenance(prov,catalog,contents['roles.sql'],bundle,
                                       authorization_sha=expected_authorization_sha,package_digest=package_digest)
        if expected_target_identity is not None:
            _require(prov['sessionUser'] == expected_target_identity['role'] and
                     prov['currentUser'] == expected_target_identity['currentRole'])
        _validate_extension_receipt(restore,prov,catalog,identity,contents['database.dump'])
        _validate_database_acl_receipt(restore,prov,catalog,identity,contents['database.dump'],prov_sha)
        _require(restore['sourceBootstrapProvenanceSha256'] == prov_sha and
                 restore['sourceBootstrapIdentity'] == identity == restore['destinationBootstrapIdentity'] and
                 restore['sourceBootstrapIdentitySha256'] == sha(canonical(identity)) == restore['destinationBootstrapIdentitySha256'])
        transport_id = restore['restoreTransportIdentity']
        _require(_identity(transport_id) == identity and transport_id['session_user'] == OWNED_RESTORE_ADMIN and
                 transport_id['current_user'] == OWNED_RESTORE_ADMIN and transport_id['serverEncoding'] == prov['serverEncoding'] and
                 restore['restoreTransportIdentitySha256'] == sha(canonical(transport_id)) and restore['transportTuple'] == OWNED_RESTORE_ADMIN_TUPLE)
        derived, receipt = _derive_roles(contents['roles.sql'],identity,restore['destinationBootstrapIdentity'])
        receipt.update(sourceBootstrapProvenanceSha256=prov_sha,destinationIdentitySha256=sha(canonical(identity)),actualStdinSha256=sha(derived))
        _require(canonical(restore['rolesDerivationReceipt']) == canonical(receipt), 'ROLE_STDIN_SHA_MISMATCH')
        wanted_hash = sha(canonical({k:catalog[k] for k in ['roles','memberships']}))
        _require(all(restore[k] == wanted_hash for k in ['postE3RoleFamilySha256','postFinalizationRoleFamilySha256','finalRoleFamilySha256']))
        _require(restore['restoreAdminNormalized'] is True and restore['restoreAdminTrackedFootprintZero'] is True and restore['footprint'] == [] and
                 restore['normalizedCatalogSha256'] == m['catalogSha256'] and restore['countsSha256'] == sha(canonical(counts)))
        stage = restore['stagedPlpgsqlValidation']; ext = prov['sourceRestorePrerequisites']['plpgsqlExpectedState']
        _require(stage['strategy'] == 'STAGED' and stage['status'] == 'PASS' and stage['extensionExpected'] == ext == stage['extensionActual'] and
                 stage['extensionSha256'] == sha(canonical(ext)) and stage['roleFamilySha256'] == wanted_hash)
        owner = ext['extensions'][0][3]; owner_row = [row for row in catalog['roles'] if row[0] == owner]
        _require(len(owner_row) == 1 and stage['owner'] == owner and stage['finalOwnerTuple'] == owner_row[0] and
                 stage['temporaryPrivilegeUsed'] is (not owner_row[0][1]) and stage['finalizationExact'] is True)
        _require(stage['databaseBefore'] == stage['databaseAfter'] and stage['databaseAclRawPreserved'] is True and
                 stage['databaseAclEffectivePreserved'] is True and stage['footprint'] == [])
        _require(restore['network'] == 'none' and type(restore['hostPorts']) is int and restore['hostPorts'] == 0 and
                 type(restore['hostMounts']) is int and restore['hostMounts'] == 0 and restore['sourceCredentialsMounted'] is False and
                 restore['imageId'] == IMAGE_ID and restore['cleanup'] == 'OWNED_CONTAINER_REMOVED' and
                 restore['ownedCleanup'] == {'status':'PASS','ownedContainersRemaining':0})
        _require(restore['databaseOwnerClassification'] == 'LOCAL_RESTORE_INFRASTRUCTURE_ONLY' and restore['databaseOwnerSourceFidelityClaim'] is False)
        phases = restore['phaseResults']
        _require(set(phases) == {'E1','E2','E3','E3_RECONCILIATION','E4','E5','E6','E6_DB_ACL','E7','E8','E9'} and
                 all(v == 'PASS' for k,v in phases.items() if k != 'E6') and phases['E6'] in ('PASS','NOT_REQUIRED'))
        _require(type(restore['aclSupplementCount']) is int and restore['aclSupplementCount'] >= 0 and
                 phases['E6'] == ('PASS' if restore['aclSupplementCount'] else 'NOT_REQUIRED'))
        return m
    except Failure: raise
    except (OSError,KeyError,TypeError,ValueError,IndexError):
        raise Failure('BACKUP_FAILED','RESTORE_EVIDENCE_BINDING_MISMATCH') from None


def _validate_backup(plan,auth,transport,fresh):
    try:
        path=Path(auth['backupDirectory'])
        if not plan.fixture and path.parent!=Path(transport.profile['backupRoot']):raise ValueError()
        if not path.is_dir() or not (path/'metadata').is_dir():raise ValueError()
        private_directory(path);private_directory(path/'metadata')
        raw=safe_file(path/'metadata/manifest.json',True)
        if sha(raw)!=auth['backupManifestSha256']:raise ValueError()
        m=strict_json(raw);now=time.time()
        risk_guard(plan,auth)
        if (m['status']!='VALID' or m['restoreStatus']!='PASS' or
            m['transportContract']!=('OWNED_ISOLATED_FIXTURE' if plan.fixture else TRANSPORT_CONTRACT) or
            m['riskAcceptance']!=(None if plan.fixture else RISK_BINDING) or
            not 0<=now-m['snapshotStart'] or (fresh and now-m['snapshotStart']>900) or not m['snapshotStart']<=m['snapshotEnd']<=m['sealedAt']<=now or
            m['planId']!=plan.data['planId'] or m['planSha256']!=plan.digest or m['targetProfile']!=plan.data['targetProfile'] or
            m['sourceIdentitySha256']!=sha(canonical(transport.identity)) or m['fullSourcePrefixDigest']!=plan.data['ledger']['sourcePrefixSha256'] or
            m['ledgerCount']!=plan.data['ledger']['expectedCount'] or m['catalogSha256']!=auth['catalogBeforeSha256'] or
            m['packageHashes']!=auth['packageHashes']):raise ValueError()
        validate_recovery_artifacts(path,auth['backupManifestSha256'],
            expected_package_digest=sha(canonical(auth['packageHashes'])),expected_plan_sha=plan.digest,
            expected_target_sha=sha(canonical(transport.identity)),expected_target_identity=transport.identity,
            expected_credential_sha=auth.get('credentialIdentitySha256'),historical=not fresh)
        required=LEGACY_FILES if m['reportVersion']=='exact-single-backup/2' else REQUIRED_FILES
        if set(m['files'])!=required:raise ValueError()
        for n,x in m['files'].items():
            data=safe_file(path/n,True)
            if sha(data)!=x['sha256'] or len(data)!=x['bytes']:raise ValueError()
        restore=strict_json(safe_file(path/'metadata/restore.json',True))
        if restore['status']!='PASS' or restore['catalogSha256']!=m['catalogSha256'] or restore['ledgerPrefixSha256']!=m['fullSourcePrefixDigest']:raise ValueError()
        bundle=strict_json(safe_file(path/'metadata/transport-proofs.json',True))
        if bundle['backupAttempt']!=m['backupAttempt'] or bundle['snapshot']!=m['snapshot']:raise ValueError()
        _validate_proofs(bundle,plan,auth,transport,m['snapshotStart'],m['snapshotEnd'],
                         {k:m['files'][v]['sha256'] for k,v in [('full','database.dump'),('schema','schema.dump'),('roles','roles.sql')]})
        return m
    except Failure as error:
        if error.code in {'BACKUP_CLIENT_TLS_PROOF_MISSING','PROVIDER_HOP_RISK_NOT_ACCEPTED','RISK_ACCEPTANCE_SCOPE_EXPIRED'}:
            raise
        raise Failure('BACKUP_FAILED') from None
    except Exception:
        raise Failure('BACKUP_FAILED') from None


def validate_backup(plan,auth,transport):
    return _validate_backup(plan,auth,transport,True)


def verification_baseline(plan,auth,transport):
    # Historical baseline remains usable for delayed UNKNOWN reconciliation.
    # A fresh read-only operator authorization is still required; this cannot apply.
    authorize(plan,auth,'READ_ONLY_VERIFY')
    _validate_backup(plan,auth,transport,False)
    return strict_json(safe_file(Path(auth['backupDirectory'])/'metadata/catalog.json',True))
